css:
.gal-factura { font-size: 12px; color: #222; }
.gal-header { display: flex; justify-content: space-between; border-bottom: 2px solid #222; padding-bottom: 8px; margin-bottom: 10px; }
.gal-empresa { font-size: 18px; font-weight: 700; }
.gal-doc { text-align: right; }
.gal-titulo { font-size: 16px; font-weight: 700; letter-spacing: 2px; }
.gal-muted { color: #666; }
.gal-no-cert { border: 2px dashed #b45309; color: #b45309; font-weight: 700; text-align: center; padding: 6px; margin: 8px 0; }
.gal-cliente, .gal-items, .gal-totales { width: 100%; border-collapse: collapse; margin-bottom: 10px; }
.gal-cliente td { padding: 2px 4px; }
.gal-items th { border-bottom: 1px solid #222; text-align: left; padding: 4px; }
.gal-items td { border-bottom: 1px solid #ddd; padding: 4px; }
.gal-r { text-align: right !important; }
.gal-totales { width: 50%; margin-left: 50%; }
.gal-totales td { padding: 2px 4px; }
.gal-total td { font-size: 15px; font-weight: 700; border-top: 1px solid #222; }
.gal-subtitulo { font-weight: 700; margin: 6px 0; }
.gal-fel { display: flex; justify-content: space-between; align-items: center; border-top: 1px solid #222; padding-top: 8px; font-size: 11px; }
.gal-qr { width: 90px; height: 90px; }
.gal-pie { text-align: center; color: #666; margin-top: 12px; }

html:
{%- set fel = doc.bfel_uuid and doc.bfel_status == "02 Procesada" -%}
{%- set bfel = frappe.db.get_value("BFEL Settings", {"company": doc.company, "enabled": 1}, ["company_nit", "nombrecomercial", "direccionemisor"], as_dict=True) or {} -%}
<div class="gal-factura">
	<div class="gal-header">
		<div>
			<div class="gal-empresa">{{ bfel.nombrecomercial or doc.company }}</div>
			{% if bfel.company_nit %}<div class="gal-muted">NIT {{ bfel.company_nit }}</div>{% endif %}
			{% if bfel.direccionemisor %}<div class="gal-muted">{{ bfel.direccionemisor }}</div>{% endif %}
		</div>
		<div class="gal-doc">
			<div class="gal-titulo">FACTURA</div>
			<div>{{ doc.name }}</div>
			<div class="gal-muted">{{ frappe.utils.formatdate(doc.posting_date) }}</div>
		</div>
	</div>

	{% if not fel %}
	<div class="gal-no-cert">DOCUMENTO NO CERTIFICADO &mdash; SIN VALIDEZ FISCAL</div>
	{% endif %}

	<table class="gal-cliente">
		<tr><td class="gal-muted">Cliente</td><td>{{ doc.customer_name }}</td>
			<td class="gal-muted">NIT</td><td>{{ doc.tax_id or doc.bfel_nit or "CF" }}</td></tr>
		{% if doc.galeria_area %}<tr><td class="gal-muted">Área</td><td colspan="3">{{ doc.galeria_area }}</td></tr>{% endif %}
	</table>

	<table class="gal-items">
		<thead><tr><th class="gal-r">Cant.</th><th>Descripción</th><th class="gal-r">Precio</th><th class="gal-r">Total</th></tr></thead>
		<tbody>
		{% for it in doc.items %}
			<tr><td class="gal-r">{{ it.get_formatted("qty") }}</td>
				<td>{{ it.item_name }}</td>
				<td class="gal-r">{{ frappe.utils.fmt_money(it.rate, currency=doc.currency) }}</td>
				<td class="gal-r">{{ frappe.utils.fmt_money(it.amount, currency=doc.currency) }}</td></tr>
		{% endfor %}
		</tbody>
	</table>

	<table class="gal-totales">
		{% if doc.discount_amount %}<tr><td>Descuento</td><td class="gal-r">-{{ frappe.utils.fmt_money(doc.discount_amount, currency=doc.currency) }}</td></tr>{% endif %}
		<tr class="gal-total"><td>TOTAL</td><td class="gal-r">{{ frappe.utils.fmt_money(doc.grand_total, currency=doc.currency) }}</td></tr>
		<tr><td class="gal-muted">IVA incluido</td><td class="gal-r gal-muted">{{ frappe.utils.fmt_money(doc.total_taxes_and_charges, currency=doc.currency) }}</td></tr>
		{% if doc.total_advance %}<tr><td>{% if doc.galeria_reservacion %}Anticipo de reserva {{ doc.galeria_reservacion }}{% else %}Anticipo recibido{% endif %}</td><td class="gal-r">-{{ frappe.utils.fmt_money(doc.total_advance, currency=doc.currency) }}</td></tr>
		<tr><td>Saldo después del anticipo</td><td class="gal-r">{{ frappe.utils.fmt_money(doc.grand_total - doc.total_advance, currency=doc.currency) }}</td></tr>{% endif %}
		<tr><td class="gal-muted">Pagado a la fecha</td><td class="gal-r gal-muted">{{ frappe.utils.fmt_money(doc.grand_total - doc.outstanding_amount, currency=doc.currency) }}</td></tr>
		{% if doc.outstanding_amount > 0 %}<tr><td>Saldo pendiente</td><td class="gal-r">{{ frappe.utils.fmt_money(doc.outstanding_amount, currency=doc.currency) }}</td></tr>{% endif %}
	</table>

	{% if not doc.payment_terms_template and doc.outstanding_amount > 0 and doc.due_date %}
	<div class="gal-subtitulo">Saldo con abonos libres &mdash; pagar antes del {{ frappe.utils.formatdate(doc.due_date) }}</div>
	{% endif %}
	{% if doc.payment_terms_template and doc.payment_schedule|length > 1 %}
	<div class="gal-subtitulo">Plan de pagos: {{ doc.payment_terms_template }}</div>
	<table class="gal-items">
		<thead><tr><th>Cuota</th><th>Vence</th><th class="gal-r">Monto</th></tr></thead>
		<tbody>
		{% for c in doc.payment_schedule %}
			<tr><td>{{ c.description or c.payment_term }}</td><td>{{ frappe.utils.formatdate(c.due_date) }}</td>
				<td class="gal-r">{{ frappe.utils.fmt_money(c.payment_amount, currency=doc.currency) }}</td></tr>
		{% endfor %}
		</tbody>
	</table>
	{% endif %}

	{% if fel %}
	<div class="gal-fel">
		<div>
			<div><b>Autorización FEL:</b> {{ doc.bfel_uuid }}</div>
			<div><b>Serie:</b> {{ doc.bfel_docto_serie or "" }} &nbsp; <b>Número:</b> {{ doc.bfel_docto_no or "" }}</div>
			{% if doc.bfel_fechacertificacion %}<div><b>Fecha de certificación:</b> {{ frappe.utils.format_datetime(doc.bfel_fechacertificacion) }}</div>{% endif %}
		</div>
		{%- set url = "https://felpub.c.sat.gob.gt/verificador-web/publico/vistas/verificacionDte.jsf?tipo=autorizacion&numero=" ~ doc.bfel_uuid ~ "&emisor=" ~ (bfel.company_nit or "") ~ "&receptor=" ~ (doc.tax_id or "CF") ~ "&monto=" ~ doc.grand_total -%}
		{%- set qr = get_qr_base64(url) -%}
		{% if qr %}<img src="{{ qr }}" class="gal-qr">{% endif %}
	</div>
	{% endif %}

	<div class="gal-pie">Gracias por su visita</div>
</div>
